    var sm=new PackageModel.Manifest(distribution,release,null,"first83",mc,"neoforge",neo,1,1,offer.signer(),i.server.entries());Path sa=stage.resolve("server.zip");PackageArchive.create(sa,sm,i.server.sources(),secret,key);FirstLaunchFiles.write(stage.resolve("pair74"),ControlWire73.sign(secret,Map.of("schema","74","release",release.toString(),"client",sha,"server",FirstLaunchFiles.hash(sa,PackageModel.MAX_ARCHIVE),"distribution",distribution.toString(),"minecraft",mc,"neoforge",neo,"signer",offer.signer())),false);DedicatedRelease74.verify(stage,pub);
